insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('improved_sanitation', '{"en": "Population living in households that use an improved sanitation facility", "hi": "बेहतर स्वच्छता सुविधा वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved sanitation", "hi": "बेहतर स्वच्छता"}'::jsonb, '{"en": "Share of people (all ages) whose household uses an improved toilet facility, as defined in the NFHS fact sheets. Survey estimate, not an administrative count.", "hi": "उन लोगों (सभी आयु) का प्रतिशत जिनका परिवार NFHS की परिभाषा के अनुसार बेहतर शौचालय सुविधा का उपयोग करता है। यह सर्वेक्षण अनुमान है, प्रशासनिक गिनती नहीं।"}'::jsonb, '%', 'multiple', true, null, 1, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('electricity', '{"en": "Population living in households with electricity", "hi": "बिजली वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Electricity", "hi": "बिजली"}'::jsonb, '{"en": "Share of people (all ages) living in households that have an electricity connection. Says nothing about hours of supply.", "hi": "बिजली कनेक्शन वाले परिवारों में रहने वाले लोगों (सभी आयु) का प्रतिशत। इससे आपूर्ति के घंटों का पता नहीं चलता।"}'::jsonb, '%', 'multiple', true, null, 2, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('clean_fuel', '{"en": "Households using clean fuel for cooking", "hi": "खाना पकाने के लिए स्वच्छ ईंधन का उपयोग करने वाले परिवार"}'::jsonb, '{"en": "Clean cooking fuel", "hi": "स्वच्छ रसोई ईंधन"}'::jsonb, '{"en": "Share of households whose main cooking fuel is clean (electricity, LPG/natural gas, biogas). This is use, not just an LPG connection, so it is lower than Ujjwala connection counts.", "hi": "उन परिवारों का प्रतिशत जिनका मुख्य रसोई ईंधन स्वच्छ है (बिजली, एलपीजी/प्राकृतिक गैस, बायोगैस)। यह वास्तविक उपयोग है, केवल एलपीजी कनेक्शन नहीं, इसलिए यह उज्ज्वला कनेक्शन संख्या से कम है।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('improved_water', '{"en": "Population living in households with an improved drinking-water source", "hi": "बेहतर पेयजल स्रोत वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved drinking water", "hi": "बेहतर पेयजल स्रोत"}'::jsonb, '{"en": "Includes piped water, public taps, tube wells and protected wells. It is not the same as a household tap connection (Jal Jeevan Mission), which will be added separately.", "hi": "इसमें पाइप से पानी, सार्वजनिक नल, ट्यूबवेल और सुरक्षित कुएँ शामिल हैं। यह घरेलू नल कनेक्शन (जल जीवन मिशन) के समान नहीं है, जिसे अलग से जोड़ा जाएगा।"}'::jsonb, '%', 'multiple', true, null, 4, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('women_bank_account', '{"en": "Women age 15-49 having a bank or savings account that they themselves use", "hi": "15-49 वर्ष की महिलाएँ जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है"}'::jsonb, '{"en": "Women''s own bank account", "hi": "महिलाओं का अपना बैंक खाता"}'::jsonb, '{"en": "Share of women age 15-49 with a bank or savings account they use themselves. Covers women only, so it is not the same as Jan Dhan account totals.", "hi": "15-49 वर्ष की उन महिलाओं का प्रतिशत जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है। यह केवल महिलाओं पर है, इसलिए जन धन खातों की कुल संख्या के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 5, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('literacy', '{"en": "Literacy rate", "hi": "साक्षरता दर"}'::jsonb, '{"en": "Literacy", "hi": "साक्षरता"}'::jsonb, '{"en": "Share of people who can read and write with understanding in any language. The Census age base changed over time (whole population before 1951, age 5+ in 1951-1971, age 7+ from 1981), marked as breaks. UNESCO''s line covers adults 15+.", "hi": "किसी भी भाषा में समझ के साथ पढ़-लिख सकने वाले लोगों का प्रतिशत। जनगणना का आयु आधार समय के साथ बदला (1951 से पहले पूरी आबादी, 1951-1971 में 5+ आयु, 1981 से 7+ आयु), जिसे विराम के रूप में दिखाया गया है। यूनेस्को की रेखा 15+ वयस्कों की है।"}'::jsonb, '%', 'multiple', true, null, 6, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('life_expectancy', '{"en": "Life expectancy at birth", "hi": "जन्म के समय जीवन प्रत्याशा"}'::jsonb, '{"en": "Life expectancy", "hi": "जीवन प्रत्याशा"}'::jsonb, '{"en": "Average years a newborn would live if current death rates held. Census actuarial estimates cover ten-year periods; SRS life tables cover five-year periods; UN figures are annual model estimates.", "hi": "यदि वर्तमान मृत्यु दरें बनी रहें तो एक नवजात के औसत जीवन वर्ष। जनगणना बीमांकिक अनुमान दस-वर्षीय अवधि के हैं; SRS जीवन तालिकाएँ पाँच-वर्षीय अवधि की; संयुक्त राष्ट्र के आँकड़े वार्षिक मॉडल अनुमान हैं।"}'::jsonb, 'years', 'multiple', true, null, 7, '[20, 80]'::jsonb, 1, '[55, 80]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('infant_mortality', '{"en": "Infant mortality rate", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Infant mortality", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Deaths before age one per 1,000 live births. Lower is better. SRS is India''s official series from 1971; pre-1947 registration undercounted deaths.", "hi": "प्रति 1,000 जीवित जन्मों पर एक वर्ष से पहले होने वाली मृत्यु। कम बेहतर है। SRS 1971 से भारत की आधिकारिक श्रृंखला है; 1947 से पहले के पंजीकरण में मृत्यु कम दर्ज होती थी।"}'::jsonb, 'per 1,000 live births', 'multiple', false, null, 8, '[0, 200]'::jsonb, 0, '[0, 100]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('gdp_per_capita', '{"en": "GDP per person (2011 international dollars, PPP)", "hi": "प्रति व्यक्ति GDP (2011 अंतरराष्ट्रीय डॉलर, PPP)"}'::jsonb, '{"en": "GDP per person", "hi": "प्रति व्यक्ति GDP"}'::jsonb, '{"en": "Average income per person, adjusted for inflation and price levels so years can be compared (Maddison Project 2023). Before 1947 the figures are academic reconstructions: Broadberry, Custodis and Gupta (2015) for 1600-1871, Heston (1983) for 1870-1900, and Maddison (1985) for 1900-46. Treat them as estimates with wide uncertainty.", "hi": "प्रति व्यक्ति औसत आय, मुद्रास्फीति और मूल्य स्तर के लिए समायोजित ताकि वर्षों की तुलना हो सके (मैडिसन प्रोजेक्ट 2023)। 1947 से पहले के आँकड़े अकादमिक पुनर्निर्माण हैं: 1600-1871 के लिए ब्रॉडबेरी, कस्टोडिस और गुप्ता (2015), 1870-1900 के लिए हेस्टन (1983), और 1900-46 के लिए मैडिसन (1985)। इन्हें काफ़ी अनिश्चितता वाले अनुमान मानें।"}'::jsonb, '2011 int. $', 'multiple', true, null, 9, '[0, 10000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('state_income_per_capita', '{"en": "Income per person in 2011-12 rupees (inflation removed): per capita Net State Domestic Product at constant 2011-12 prices", "hi": "2011-12 के रुपयों में प्रति व्यक्ति आय (मुद्रास्फीति हटाकर): स्थिर 2011-12 मूल्यों पर प्रति व्यक्ति शुद्ध राज्य घरेलू उत्पाद"}'::jsonb, '{"en": "Income per person (2011-12 ₹)", "hi": "प्रति व्यक्ति आय (2011-12 ₹)"}'::jsonb, '{"en": "Average income produced per person, valued at 2011-12 prices so that inflation is removed and years can be compared. It is NOT what people earn in today''s rupees: at 2024-25''s own prices the all-India figure is roughly ₹2 lakh. It is also net of depreciation, so it is lower than GDP per person. To convert to dollars, use the 2011 rates: about ₹46.7 per US$ (market) or ₹15.5 per international $ (PPP, World Bank).", "hi": "प्रति व्यक्ति औसत आय, 2011-12 के मूल्यों पर, ताकि मुद्रास्फीति हट जाए और वर्षों की तुलना हो सके। यह आज के रुपयों में कमाई नहीं है: 2024-25 के अपने मूल्यों पर अखिल भारतीय आँकड़ा लगभग ₹2 लाख है। यह मूल्यह्रास के बाद की शुद्ध आय है, इसलिए प्रति व्यक्ति GDP से कम है। डॉलर में बदलने के लिए 2011 की दरें लें: लगभग ₹46.7 प्रति अमेरिकी डॉलर (बाज़ार) या ₹15.5 प्रति अंतरराष्ट्रीय डॉलर (PPP, विश्व बैंक)।"}'::jsonb, '₹ in 2011-12 prices', 'multiple', true, null, 10, '[0, 400000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('open_defecation', '{"en": "Households with no toilet facility (open defecation)", "hi": "बिना शौचालय सुविधा वाले परिवार (खुले में शौच)"}'::jsonb, '{"en": "Open defecation", "hi": "खुले में शौच"}'::jsonb, '{"en": "Share of households that use no toilet facility (open field, bush). Lower is better. NFHS data tabulated by The DHS Program with a standard definition across all five rounds, 1992-93 to 2019-21.", "hi": "उन परिवारों का प्रतिशत जो किसी शौचालय सुविधा का उपयोग नहीं करते (खुला मैदान, झाड़ी)। कम बेहतर है। NFHS आँकड़े, DHS प्रोग्राम द्वारा पाँचों दौर (1992-93 से 2019-21) में एक मानक परिभाषा से सारणीबद्ध।"}'::jsonb, '%', 'multiple', false, null, 2, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('toilet_any', '{"en": "Households with any toilet or latrine facility", "hi": "किसी भी शौचालय सुविधा वाले परिवार"}'::jsonb, '{"en": "Any toilet (1992-2006)", "hi": "कोई भी शौचालय (1992-2006)"}'::jsonb, '{"en": "As printed in the NFHS-1, 2 and 3 India reports. Counts any toilet, shared or not, so it is not the same as ''improved sanitation''. NFHS-1 values come from a scanned report and are lower-confidence.", "hi": "NFHS-1, 2 और 3 भारत रिपोर्ट में छपे अनुसार। कोई भी शौचालय, साझा हो या नहीं, गिना जाता है, इसलिए यह ''बेहतर स्वच्छता'' के समान नहीं है। NFHS-1 के मान स्कैन रिपोर्ट से हैं और कम विश्वसनीय हैं।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('tap_water', '{"en": "Households whose main source of drinking water is a tap", "hi": "वे परिवार जिनका पीने के पानी का मुख्य स्रोत नल है"}'::jsonb, '{"en": "Tap water", "hi": "नल का पानी"}'::jsonb, '{"en": "Census of India houselisting: households whose main drinking-water source is tap water (2011 adds treated and untreated sources together, as printed). Not the same as Jal Jeevan Mission ''functional household tap connections''.", "hi": "भारत की जनगणना मकान सूचीकरण: वे परिवार जिनका पीने के पानी का मुख्य स्रोत नल है (2011 में उपचारित और अनुपचारित स्रोत मिलाकर, जैसा छपा है)। यह जल जीवन मिशन के ''कार्यात्मक घरेलू नल कनेक्शन'' के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 4, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('household_banking', '{"en": "Households availing banking services", "hi": "बैंकिंग सेवाओं का लाभ उठाने वाले परिवार"}'::jsonb, '{"en": "Household banking", "hi": "घरेलू बैंकिंग"}'::jsonb, '{"en": "Census of India 2001 and 2011: households where any member has a bank account or uses banking services. Not the same as individual accounts (Findex) or Jan Dhan totals.", "hi": "भारत की जनगणना 2001 और 2011: वे परिवार जिनके किसी सदस्य का बैंक खाता है या जो बैंकिंग सेवाओं का उपयोग करते हैं। यह व्यक्तिगत खातों (फ़िंडेक्स) या जन धन के कुल योग के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 6, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('toilet_premises', '{"en": "Households with a latrine within the premises", "hi": "परिसर के भीतर शौचालय वाले परिवार"}'::jsonb, '{"en": "Toilet at home (Census)", "hi": "घर में शौचालय (जनगणना)"}'::jsonb, '{"en": "Census of India: 2001 asked about a latrine ''within the house'', 2011 ''within the premises''. ORGI compares the two directly.", "hi": "भारत की जनगणना: 2001 में ''घर के भीतर'' शौचालय के बारे में पूछा गया, 2011 में ''परिसर के भीतर''। ORGI दोनों की सीधे तुलना करता है।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
