insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census2011-hhaa-visualizing-maps', 'Office of the Registrar General & Census Commissioner, India', 'Census of India 2011 - Houses, Household Amenities And Assets Data 2011 - Visualizing Through Maps (presentation PDF)', 'https://censusindia.gov.in/nada/index.php/catalog/42574/download/46198/Census%20of%20India%202011-Houses%2C%20Household%20Amenities%20And%20Assets%20Data%202011%20-%20Visualizing%20Through%20Maps.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'All-India summary tables printed in the ORGI release presentation for the 2011 Houselisting and Housing Census, read from pdftotext -raw text. 2011 values cross-checked against counts in 2011 India tables HH-6, HH-7, HH-8, HH-10 and HH-12.', 'India only; 2011, plus 2001 where a slide prints the comparison (latrine within premises, banking).', 'National figures only; State values appear only as map shading. 2011 households exclude institutional households. This deck prints 53.0% of households without latrine within premises, while ORGI''s ''Availability and type of latrine facility 2001-2011'' table prints no_latrine_2011 = 53.1.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census2011-hl14-chandigarh', 'Office of the Registrar General & Census Commissioner, India', 'HL-14 (Table HH-14): Percentage of households to total households by amenities and assets, Chandigarh, district Chandigarh - 2011', 'https://censusindia.gov.in/nada/index.php/catalog/9353/download/12465/HLPCA-04055-2011_H14_census.xlsx', 'A', 'Government of India publication; reuse with attribution to the source', 'Excel table read with openpyxl; row 8 (''District - Chandigarh'', Total). Chandigarh had a single district in 2011, so the district row covers the whole UT.', 'Chandigarh UT, Census 2011, total households (excluding institutional households).', 'Percentages printed to one decimal. Tap water is printed only as two columns (treated / un-treated source) with no total, so tap_water is not recorded.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
