insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs2-india-report', 'International Institute for Population Sciences (IIPS) and ORC Macro (copy hosted by The DHS Program, ICF)', 'National Family Health Survey (NFHS-2), 1998-99: India (2000)', 'https://dhsprogram.com/pubs/pdf/FRIND2/FRIND2.pdf', 'A', 'Government of India / IIPS publication', 'Household survey 1998-99; Table 2.12 Housing characteristics by state (% of households).', 'India and 25 states; Tripura not in report (fieldwork delayed)', 'Undivided MP/UP/Bihar and AP. Water and fuel columns (piped or hand pump; biomass) don''t match the requested indicators, so they weren''t used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
