insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('dhs-api-CO_MOBB_W_BNK', 'The DHS Program (ICF), tabulations of NFHS data (IIPS/MoHFW)', 'DHS Program Indicator Data API: Women who have a bank account (CO_MOBB_W_BNK), India NFHS-1 to NFHS-5', 'https://api.dhsprogram.com/rest/dhs/data?countryIds=IA&indicatorIds=CO_MOBB_W_BNK&breakdown=subnational&f=json&perpage=1000', 'B', 'The DHS Program data, free to use with attribution', 'DHS recalculation from NFHS microdata to DHS standard definitions. State values come from breakdown=subnational and India from breakdown=national (same query with breakdown=national). Surveys IA1993DHS, IA1999DHS, IA2006DHS, IA2015DHS, IA2020DHS; IsPreferred rows only.', 'States as surveyed in each round (25 in NFHS-1, 26 in NFHS-2, 29 in NFHS-3, 34 states/UTs in NFHS-4, 36 in NFHS-5) plus India', 'Values can differ slightly from printed NFHS reports (NFHS-4/5 checked: within 0.1 point of the fact sheets). DHS-built aggregates such as ''Bihar, inc Jharkhand'' for post-2000 rounds, NFHS-1 ''Jammu region'', and NFHS-4 separate DNH / Daman & Diu were skipped.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2023-24-t01', 'Reserve Bank of India (Handbook of Statistics on Indian States 2023-24); original source: Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 1: State-wise Total Population (thousands), census years 1951-2011', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/1T_09122024203D0FF3A7FC42068D952BA8D5603050.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Decennial Census total population (persons) as compiled by RBI, printed in thousands; converted to persons by multiplying by 1,000. DH = Dadra & Nagar Haveli + Daman & Diu (printed separately) summed. Taken from the 2023-24 edition because the latest (2024-25) edition has no population table. Cells printed ''-'' skipped.', '35 states/UTs (incl. DH as a sum) plus All India; 1951, 1961, 1971, 1981, 1991, 2001, 2011; 244 values', 'Rounded to the nearest thousand in the source, so persons values are approximate (+/-500; +/-1,000 for the DH sum). Assam 1981 and Jammu & Kashmir 1991 are interpolated (no census held). Arunachal Pradesh first enumerated in 1961. India and Manipur 2001 include estimated population of three Senapati sub-divisions. Andhra Pradesh is undivided (no Telangana row); Jammu & Kashmir includes Ladakh (no Ladakh row). Table note says efforts were made to cover newly created states, i.e. figures appear to be on present-day boundaries.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2023-24-t06', 'Reserve Bank of India (Handbook of Statistics on Indian States 2023-24); original source: Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 6: State-wise Literacy Rate (per cent), census years 1951-2011', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/6T_091220248DDB438F8E2C497E8FF554B50EB84197.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Persons literacy rate from each decennial Census as compiled by RBI. Values copied exactly from the Excel table; cells printed as ''-'' (not available) skipped. Taken from the 2023-24 edition because the latest (2024-25) edition dropped the literacy table.', '34 states/UTs plus All India; 1951, 1961, 1971, 1981, 1991, 2001, 2011; 215 values', 'Age base changes: 1951-71 rates relate to population aged 5+, 1981-2011 to aged 7+ (break flagged at first 7+ point). 1951 West Bengal relates to total population incl. 0-4; 1951 Chhattisgarh, Madhya Pradesh, Manipur based on sample population. 2001 India and Manipur exclude three Senapati sub-divisions. Andhra Pradesh is undivided (no Telangana row); Jammu & Kashmir includes Ladakh. Table does not state the territorial basis for pre-2001 figures, though it gives separate figures for Chhattisgarh, Jharkhand and Uttarakhand back to 1951. Dadra & Nagar Haveli and Daman & Diu are printed separately and were left out.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t04', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Sample Registration System Bulletin, Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 4: State-wise Infant Mortality Rate (per thousand live births), 2004-2023', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/4T_11122025025F203A250E46CAB963946C776ADBAF.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'SRS infant deaths per 1,000 live births, total, as compiled by RBI. Values copied exactly; ''.'' (not applicable) and ''-'' (not available) skipped. Dadra & Nagar Haveli values marked ''*'' (2020-2023, footnote: include Daman & Diu) mapped to DH with the marker stripped.', '35 states/UTs plus All India; annual 2004-2023; 694 values', 'Andhra Pradesh is undivided up to 2013 (Telangana not applicable); break flagged at 2014. Table gives no note on whether Jammu & Kashmir includes Ladakh after 2019; no Ladakh row. Dadra & Nagar Haveli and Daman & Diu printed separately for 2004-2019 and left out. SRS estimates for small states/UTs are based on small samples and fluctuate year to year.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t07', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: SRS Abridged Life Tables, Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 7: State-wise Life Expectancy (years at birth), 1993-97 to 2019-23', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/7T_11122025164B47839F9943F2BC176783B25CB079.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Expectation of life at birth, ''Total'' column (persons), five-year moving periods from SRS abridged life tables. Values copied exactly; ''-'' skipped. Year = end year of the period.', '22 states plus All India; 27 periods 1993-97 to 2019-23; 527 values', 'Only major states are covered (no NE states other than Assam, no UTs other than Delhi). Bihar, Madhya Pradesh and Uttar Pradesh include Jharkhand, Chhattisgarh and Uttarakhand till 2009-13 (break flagged at 2010-14). Andhra Pradesh includes Telangana till 2013-17 (break at 2014-18). Jammu & Kashmir includes Ladakh in all periods. Overlapping five-year periods are not independent observations.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t20', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: National Statistical Office, Ministry of Statistics and Programme Implementation', 'Table 20: Per Capita Net State Domestic Product (Constant Prices, base 2011-12, rupees), 2011-12 to 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/20T_111220252B6EE27737FD4931A99C5A448B7CEC68.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita NSDP at constant 2011-12 prices in rupees, by fiscal year, as compiled by RBI from NSO/MoSPI. Values copied exactly; ''-'' skipped. Year = end year of the fiscal year (2011-12 -> 2012).', '33 states/UTs; fiscal years 2011-12 to 2024-25; 453 values', 'No All-India row in this table (India per capita NNI not included here). Jammu & Kashmir includes Ladakh for 2011-12 to 2018-19 and is UT of J&K only from 2019-20 (break flagged). Telangana is listed from 2011-12, so Andhra Pradesh figures are for residual AP throughout. No Ladakh, Lakshadweep or Dadra & Nagar Haveli and Daman & Diu rows. The table does not flag provisional years, but recent state accounts estimates are routinely revised by MoSPI; several states have no 2024-25 (and Gujarat no 2023-24) figure.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('comtrade-india-neighbours', 'United Nations Statistics Division, UN Comtrade Database (data as reported to the UN by India: Directorate General of Commercial Intelligence and Statistics, Ministry of Commerce and Industry)', 'UN Comtrade: India (reporter 699), annual merchandise trade, all commodities (HS TOTAL), exports and imports by partner', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=699&partnerCode=156,586,50,524,64,144,104,462,4&period=2023&flowCode=X,M&cmdCode=TOTAL', 'B', 'UN Comtrade terms of use (https://comtradeplus.un.org/); free public preview API, cite as ''United Nations Comtrade Database''. No explicit open licence was checked during this task.', 'Fetched with scripts/data/fetch_trade.py from the keyless public preview API, one call per calendar year 1988-2026 (the preview allows only one period per call, max 500 records), all nine partners and both flows per call. Kept records with partner2Code 0, customsCode C00, motCode 0, cmdCode TOTAL. exports_usd = flow X primaryValue, imports_usd = flow M primaryValue, copied as returned (US$, decimals kept). The HS vintage of each year (H0-H6) is recorded in the note column. Five partner-years (CN 2024, BD 2010, PK 2019, NP 1995, AF 2021) were re-queried separately and matched exactly.', 'India with China, Pakistan, Bangladesh, Nepal, Bhutan, Sri Lanka, Myanmar, Maldives and Afghanistan; calendar years 1988-2025; 340 partner-years with both exports and imports. Bhutan 1988-1989 has no India-reported record (blank rows). 2026 not yet available as of 2026-10-16.', 'Reporter versus partner (mirror) data: these are India''s own declarations. The partner''s figures for the same trade differ, because imports are valued CIF and exports FOB, because of timing, classification and country-of-origin versus consignment rules, and because of unrecorded or informal border trade (large for Nepal, Bangladesh, Myanmar and Afghanistan). Example: for 2023 China reported imports from India of US$18.54 bn and exports to India of US$117.68 bn, against India''s figures of US$16.25 bn exports to and US$121.97 bn imports from China. Exports include re-exports and imports include goods re-imported; goods shipped through third countries (for example India-Pakistan trade via the UAE or Singapore) are counted against the intermediate country, not the neighbour, so trade with Pakistan and Afghanistan in particular is understated. Values are nominal current US$ converted by India at its own exchange rates; they are not adjusted for inflation or rupee movements. Calendar years, not India''s April-March fiscal year, so they do not match Ministry of Commerce annual totals. HS revisions (H0 to H6) change detail but not the TOTAL concept. Recent years, especially 2025, may be revised. Comtrade flags these annual totals as aggregates (isAggregate true, isReported false), i.e. summed by UNSD from India''s detailed submission. Cross-check against the Ministry of Commerce Export Import Data Bank (tradestat.commerce.gov.in, country-wise total trade, US$ million, fiscal years) is broadly consistent for imports; on 2026-10-16 the EIDB page showed 2023-24 export figures roughly double the adjacent years for all nine partners (e.g. China 33,317.82 vs 15,306.10 in 2022-23 and 14,252.21 in 2024-25), which looks like an error on that page.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
